<?php
declare(strict_types=1);
trait AdminOperations {
    public function dashboard():array{$count=fn($table,$where='1=1')=>(int)$this->one("SELECT COUNT(*) n FROM $table WHERE $where")['n'];return ['members'=>$count('members'),'signed'=>$count('contracts',"state='SIGNED'"),'pending_center'=>$count('contracts',"state='SIGNED' AND center_accepted_at IS NULL"),'drafts'=>$count('drafts'),'pending_innux'=>$count('contracts',"state='SIGNED' AND member_id IN (SELECT id FROM members WHERE innux_state NOT IN ('MANUALLY_CONFIRMED','VERIFIED_READ_ONLY','VERIFIED_CONNECTOR','CANCELLED'))"),'pending_dues'=>$count('dues',"state='PREPARED'"),'pending_withdrawals'=>$count('withdrawals',"state='PENDING'"),'batches'=>$this->batches()];}
    public function saveTariff(array $r):array{$name=textField($r,'name',120);$brand=textField($r,'brand',12);ensure(in_array($brand,['fitness','fighters'],true),'Marca no válida.');$amounts=[];foreach(['monthly_cents','enrollment_cents','max_discount'] as $k){$v=filter_var($r[$k]??null,FILTER_VALIDATE_INT);ensure($v!==false&&$v>=0&&$v<=($k==='max_discount'?100:10000000),'Revisa los importes o el descuento.');$amounts[$k]=$v;}$conditions=textField($r,'conditions',2000);$id=(string)($r['id']??'')?:uuid();return $this->transaction(function()use($r,$id,$name,$brand,$amounts,$conditions){$a=[$name,$brand,$amounts['monthly_cents'],$amounts['enrollment_cents'],$amounts['max_discount'],$conditions,(int)(($r['active']??true)===true),$id];if($this->one('SELECT id FROM tariffs WHERE id=?',[$id]))$this->sql('UPDATE tariffs SET name=?,brand=?,monthly_cents=?,enrollment_cents=?,max_discount=?,conditions=?,active=?,revision=revision+1 WHERE id=?',$a);else $this->sql('INSERT INTO tariffs(name,brand,monthly_cents,enrollment_cents,max_discount,conditions,active,id) VALUES(?,?,?,?,?,?,?,?)',$a);$this->audit($this->actor(),'TARIFF_SAVED',$id);return ['id'=>$id];});}
    public function saveLegal(array $r):array{$brand=textField($r,'brand',12);ensure(in_array($brand,['fitness','fighters'],true),'Marca no válida.');$version=textField($r,'version',80);$texts=[];foreach(['contract_text','privacy_text','bank_text','sepa_text'] as $k)$texts[] = textField($r,$k,16000);$approved=($r['approved']??false)===true;$reference=textField($r,'approval_reference',300,$approved);$id=uuid();return $this->transaction(function()use($brand,$version,$texts,$approved,$reference,$id){$this->sql('UPDATE legal_versions SET active=0 WHERE brand=?',[$brand]);$this->sql('INSERT INTO legal_versions(id,brand,version,contract_text,privacy_text,bank_text,sepa_text,approved,approval_reference,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',array_merge([$id,$brand,$version],$texts,[(int)$approved,$reference,instant()]));$this->audit($this->actor(),'LEGAL_VERSION_CREATED',$id,['approved'=>$approved]);return ['id'=>$id];});}
    public function saveProfile(array $r):array{$format=textField($r,'format',10);ensure(in_array($format,['csv','xlsx'],true),'XML SEPA requiere la variante y versión confirmadas por el banco.');$name=textField($r,'name',120);$mapping=$r['mapping']??null;ensure(is_array($mapping)&&count($mapping)>0&&count($mapping)<=40,'Configura entre 1 y 40 columnas según la plantilla real.');$allowed=['member_reference','innux_number','member_name','holder','iban','amount','period','concept','due_date','mandate_reference','creditor_id','contract_reference','constant'];$clean=[];foreach($mapping as $map){$header=textField($map,'header',100);$field=textField($map,'field',30);ensure(in_array($field,$allowed,true),'Campo de exportación no válido.');$clean[]=['header'=>$header,'field'=>$field,'value'=>textField($map,'value',200,false)];}$delimiter=(string)($r['delimiter']??';');ensure(in_array($delimiter,[';',',',"\t"],true),'Separador no válido.');$decimal=(string)($r['decimal_separator']??',');ensure(in_array($decimal,[',','.'],true),'Separador decimal no válido.');$approved=($r['approved']??false)===true;$bankref=textField($r,'bank_reference',500,$approved);$id=($r['id']??'')?:uuid();return $this->transaction(function()use($name,$id,$format,$clean,$delimiter,$decimal,$approved,$bankref,$r){$args=[$name,$format,jencode($clean),$delimiter,$decimal,(int)$approved,$bankref,(int)(($r['active']??true)===true),$id];if($this->one('SELECT id FROM export_profiles WHERE id=?',[$id]))$this->sql('UPDATE export_profiles SET name=?,format=?,mapping_json=?,delimiter=?,decimal_separator=?,approved=?,bank_reference=?,active=?,revision=revision+1 WHERE id=?',$args);else $this->sql('INSERT INTO export_profiles(name,format,mapping_json,delimiter,decimal_separator,approved,bank_reference,active,id) VALUES(?,?,?,?,?,?,?,?,?)',$args);$this->audit($this->actor(),'EXPORT_PROFILE_SAVED',$id,['approved'=>$approved]);return ['id'=>$id];});}
    public function configView():array{return ['tariffs'=>$this->sql('SELECT * FROM tariffs ORDER BY name'),'legal'=>$this->sql('SELECT * FROM legal_versions ORDER BY created_at DESC'),'profiles'=>$this->sql('SELECT * FROM export_profiles ORDER BY name'),'users'=>$this->sql('SELECT id,username,role,active,created_at FROM users ORDER BY username'),'creditor'=>json_decode($this->one("SELECT value FROM settings WHERE name='creditor'")['value']??'{}',true),'retention'=>json_decode($this->one("SELECT value FROM settings WHERE name='retention'")['value']??'{}',true)];}
    public function saveUser(array $r):array{$username=textField($r,'username',60);ensure(preg_match('/^[a-zA-Z0-9_.-]{3,60}$/',$username)===1,'Usuario: usa letras, números, punto o guion.');$role=textField($r,'role',15);ensure(in_array($role,['admin','staff','finance','viewer'],true),'Rol no válido.');$active=($r['active']??true)===true;$password=(string)($r['password']??'');$id=($r['id']??'')?:uuid();$existing=$this->one('SELECT * FROM users WHERE id=?',[$id]);ensure($existing||$password!=='','Indica una contraseña inicial.');if($password!=='')ensure(strlen($password)>=12&&strlen($password)<=200&&preg_match('/[A-Za-z]/',$password)&&preg_match('/[0-9]/',$password),'Contraseña: al menos 12 caracteres, letras y cifras.');return $this->transaction(function()use($id,$username,$role,$active,$password,$existing){if($existing&&$existing['role']==='admin'&&(!$active||$role!=='admin'))ensure((int)$this->one("SELECT COUNT(*) n FROM users WHERE role='admin' AND active=1 AND id<>?",[$id])['n']>0,'Debe quedar un administrador activo.');$hash=$password!==''?password_hash($password,PASSWORD_ARGON2ID):($existing['password_hash']??'');if($existing)$this->sql('UPDATE users SET username=?,role=?,active=?,password_hash=?,epoch=epoch+1 WHERE id=?',[$username,$role,(int)$active,$hash,$id]);else $this->sql('INSERT INTO users(id,username,role,active,password_hash,created_at) VALUES(?,?,?,?,?,?)',[$id,$username,$role,(int)$active,$hash,instant()]);$this->audit($this->actor(),'USER_SAVED',$id);return ['id'=>$id];});}
    public function pendingDrafts():array{$out=[];foreach($this->sql('SELECT * FROM drafts WHERE expires_at>? ORDER BY updated_at DESC',[instant()]) as $d){$p=$this->open($d['data_enc']);$out[]=['id'=>$d['id'],'name'=>trim(($p['personal']['name']??'').' '.($p['personal']['surname']??''))?:'Alta en curso','state'=>$d['review_hash']?'SIGNATURE_PENDING':'INCOMPLETE','discount_percent'=>$d['discount_percent'],'updated_at'=>$d['updated_at']];}return $out;}
    public function discountDraft(array $r):array{$id=textField($r,'id',32);$percent=filter_var($r['percent']??null,FILTER_VALIDATE_INT);ensure($percent!==false&&$percent>=0&&$percent<=100,'Descuento no válido.');$reason=textField($r,'reason',400);return $this->transaction(function()use($id,$percent,$reason){$d=$this->one('SELECT * FROM drafts WHERE id=?',[$id]);ensure($d,'Borrador no encontrado.',404);$data=$this->open($d['data_enc']);$tariff=$this->one('SELECT max_discount FROM tariffs WHERE id=?',[$data['tariff_id']??'']);ensure($tariff&&$percent<=(int)$tariff['max_discount'],'El descuento supera el autorizado en la tarifa.');$this->sql('UPDATE drafts SET discount_percent=?,discount_reason=?,discount_actor=?,review_enc=NULL,review_hash=NULL WHERE id=?',[$percent,$this->vault->encrypt($reason,'discount_reason'),$this->actor(),$id]);$this->audit($this->actor(),'DISCOUNT_AUTHORIZED',$id,['percent'=>$percent]);return ['updated'=>true];});}
    public function saveSettings(array $r):array{$name=textField($r,'name',30);ensure(in_array($name,['creditor','retention'],true),'Configuración no válida.');$value=$r['value']??[];ensure(is_array($value)&&strlen(jencode($value))<6000,'Configuración demasiado grande.');if($name==='creditor')$value=['name'=>textField($value,'name',160),'id'=>textField($value,'id',80)];else $value=['policy_reference'=>textField($value,'policy_reference',300),'approved_by'=>textField($value,'approved_by',100),'instructions'=>textField($value,'instructions',4000),'automatic_deletion'=>false];return $this->transaction(function()use($name,$value){$this->sql('INSERT INTO settings VALUES(?,?) ON CONFLICT(name) DO UPDATE SET value=excluded.value',[$name,jencode($value)]);$this->audit($this->actor(),'SETTINGS_SAVED',$name);return ['saved'=>true];});}
    public function auditList():array{$out=$this->sql('SELECT id,created_at,actor,action,target,hash FROM audit ORDER BY id DESC LIMIT 250');foreach($out as &$r){$r['actor_name']=$this->actorDisplay($r['actor']);$r['action_label']=$this->actionDisplay($r['action']);}return $out;}
    public function verifyAudit():bool{$prev='';foreach($this->sql('SELECT * FROM audit ORDER BY id') as $r){$hash=hash_hmac('sha256',jencode([$r['created_at'],$r['actor'],$r['action'],$r['target'],$r['detail_json'],$prev]),$this->vault->key('audit'));if($r['previous_hash']!==$prev||!hash_equals($r['hash'],$hash))return false;$prev=$hash;}return true;}
    public function createBackup():array{$id=uuid();$dir=$this->root.'/.private/backups';if(!is_dir($dir))mkdir($dir,0700,true);$temp=$dir.'/'.$id.'.sqlite';try{$this->db->exec('VACUUM INTO '.$this->db->quote($temp));$bytes=file_get_contents($temp);$blob='TFBACKUP1\n'.$this->vault->encrypt($bytes,'backup');file_put_contents($dir.'/'.$id.'.tfbackup',$blob,LOCK_EX);}finally{if(is_file($temp))unlink($temp);}$this->transaction(fn()=>$this->audit($this->actor(),'ENCRYPTED_BACKUP_CREATED',$id,['sha256'=>hash('sha256',$bytes)]));return ['id'=>$id,'filename'=>'TopFitness-'.$id.'.tfbackup'];}
    public function privacyRequest(array $r):array{$id=uuid();$member=textField($r,'member_id',32);$reason=textField($r,'reason',1000);$this->transaction(function()use($id,$member,$reason){ensure($this->one('SELECT id FROM members WHERE id=?',[$member]),'Socio no encontrado.');$this->sql('INSERT INTO privacy_requests(id,member_id,reason,actor,created_at) VALUES(?,?,?,?,?)',[$id,$member,$this->vault->encrypt($reason,'privacy'),$this->actor(),instant()]);$this->audit($this->actor(),'PRIVACY_REVIEW_REQUESTED',$member);});return ['id'=>$id,'state'=>'PENDING_REVIEW','message'=>'No se han eliminado documentos. Requiere la política aprobada y revisión de obligaciones y copias.'];}
}
